As informações de um departamento e de seus colaboradores devem ser organizadas e armazenadas conforme a estrutura mostrada no diagrama precedente. Para isso, serão utilizados os comandos DDL a seguir.

create table organograma (id integer primary key, descricao varchar(50), cargo varchar(50), pai integer, constraint fk_organograma foreign key (pai) references organograma);

create table colaborador (cpf bigint primary key, nome varchar(50), data_nascimento date);

create table colaborador_organograma (cpf bigint, cargo integer, data_nomeacao date, data_exoneracao date, constraint pk_colaborador_organograma primary key (cpf, cargo), constraint fk_colaborador_organograma_cpf foreign key (cpf) references colaborador, constraint fk_colaborador_organograma_cargo foreign key (cargo) references organograma (id)).

